export type Maybe<T> = T | null;
export type InputMaybe<T> = Maybe<T>;
/** All built-in and custom scalars, mapped to their actual values */
export type Scalars = {
  ID: { input: string; output: string; }
  String: { input: string; output: string; }
  Boolean: { input: boolean; output: boolean; }
  Int: { input: number; output: number; }
  Float: { input: number; output: number; }
  BigInt: { input: any; output: any; }
  Byte: { input: any; output: any; }
  /** A construction kit version. */
  CkVersion: { input: any; output: any; }
  /** The `DateTime` scalar type represents a date and time. `DateTime` expects timestamps to be formatted in accordance with the [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601) standard. */
  DateTime: { input: any; output: any; }
  /** The `DateTimeOffset` scalar type represents a date, time and offset from UTC. `DateTimeOffset` expects timestamps to be formatted in accordance with the [ISO-8601](https://en.wikipedia.org/wiki/ISO_8601) standard. */
  DateTimeOffset: { input: any; output: any; }
  Decimal: { input: any; output: any; }
  LargeBinary: { input: any; output: any; }
  Long: { input: any; output: any; }
  /** A unique identifier for an runtime object. */
  OctoObjectId: { input: string; output: string; }
  /** A runtime construction kit id of CkAssociationRoleId. */
  RtCkAssociationRoleId: { input: any; output: any; }
  /** A runtime construction kit id of CkEnumId. */
  RtCkEnumId: { input: any; output: any; }
  /** A runtime construction kit id of CkRecordId. */
  RtCkRecordId: { input: any; output: any; }
  /** A runtime construction kit id of CkTypeId. */
  RtCkTypeId: { input: any; output: any; }
  /** The `Seconds` scalar type represents a period of time represented as the total number of seconds in range [-922337203685, 922337203685]. */
  Seconds: { input: any; output: any; }
  SimpleScalar: { input: any; output: any; }
  ULong: { input: any; output: any; }
  Uri: { input: any; output: any; }
};

/** Defines the type of aggregation for runtime queries. */
export type AggregationInputTypes =
  | 'AVERAGE'
  | 'COUNT'
  | 'MAXIMUM'
  | 'MINIMUM'
  | 'SUM';

/** Defines the aggregation type */
export type AggregationType =
  | 'AVG'
  | 'COUNT'
  | 'INTEGRAL'
  | 'MAX'
  | 'MIN'
  | 'STATE_DURATION'
  | 'SUM'
  | 'TIME_WEIGHTED_AVG';

/** Defines the type of aggregation for runtime query results. */
export type AggregationTypes =
  | 'AVERAGE'
  | 'COUNT'
  | 'INTEGRAL'
  | 'MAXIMUM'
  | 'MINIMUM'
  | 'NONE'
  | 'STATE_DURATION'
  | 'SUM'
  | 'TIME_WEIGHTED_AVERAGE';

/** Attribute path to capture as a CrateDB column on the archive table, plus index/required flags. */
export type ArchiveColumnSpecInput = {
  /** When true (default), CrateDB indexes the column by its standard rules. False emits INDEX OFF. */
  indexed: Scalars['Boolean']['input'];
  /** Attribute path on the target CK type (e.g. 'energyConsumed', 'sensor.reading.value'). */
  path: Scalars['String']['input'];
  /** When true, every insert must supply a non-null value for this path. */
  required: Scalars['Boolean']['input'];
};

/** One rung of an archive family with its grain and MEASURED data coverage. availableFrom/availableTo are both null when the archive holds no data. */
export type ArchiveCoverageInfo = {
  __typename?: 'ArchiveCoverageInfo';
  /** Runtime id of the archive this row describes. */
  archiveRtId: Scalars['OctoObjectId']['output'];
  /** Earliest timestamp with data on this rung (measured). Null when the archive holds no data. */
  availableFrom?: Maybe<Scalars['DateTime']['output']>;
  /** Latest timestamp with data on this rung (measured). Null when the archive holds no data. */
  availableTo?: Maybe<Scalars['DateTime']['output']>;
  /** Bucket-boundary alignment of the rung (FixedSize for base archives). */
  bucketAlignment: BucketAlignment;
  /** Bucket width in milliseconds for a rollup rung; null for a base archive. */
  bucketSizeMs?: Maybe<Scalars['Long']['output']>;
  /** True for a raw / time-range archive (no rollup sources), false for a rollup rung. */
  isBase: Scalars['Boolean']['output'];
  /** Optional well-known name of the archive. */
  rtWellKnownName?: Maybe<Scalars['String']['output']>;
  /** Current lifecycle status: Created / Activated / Disabled / Failed. */
  status: Scalars['String']['output'];
  /** Aggregation functions stored on this rung; empty for a base archive. */
  storedFunctions: Array<CkRollupFunction>;
};

/** Attribute path reachable from a CK type, suitable for use as a CkArchive column. */
export type ArchivePathInfo = {
  __typename?: 'ArchivePathInfo';
  /** CK type id from which the leaf attribute is inherited, when not the queried type itself. */
  inheritedFromCkTypeId?: Maybe<Scalars['String']['output']>;
  /** True when the path traverses or terminates on an array attribute. */
  isArray: Scalars['Boolean']['output'];
  /** True when the path terminates on a record attribute. */
  isRecord: Scalars['Boolean']['output'];
  /** Dot-separated attribute path, e.g. "voltage" or "sensor.reading.value". */
  path: Scalars['String']['output'];
  /** Leaf primitive type when the path terminates on a scalar; null for records. */
  primitiveType?: Maybe<AttributeValueType>;
  /** CK record id of the record terminating the path; null for scalars. */
  recordTypeId?: Maybe<Scalars['String']['output']>;
};

/** Backend-agnostic health classification: Unknown / Good / Warning / Critical. */
export type ArchiveStorageHealth =
  | 'CRITICAL'
  | 'GOOD'
  | 'UNKNOWN'
  | 'WARNING';

/** Per-archive backend storage stats — row count, on-disk size, health classification. Backend-agnostic; the underlying CrateDB provider maps its native signals onto the Health enum so clients don't have to know about shards or replicas. */
export type ArchiveStorageStats = {
  __typename?: 'ArchiveStorageStats';
  /** Runtime id of the archive these stats describe. */
  archiveRtId: Scalars['OctoObjectId']['output'];
  /** Overall health classification. Unknown means the provider could not determine a state — render distinctly from Good. */
  health: ArchiveStorageHealth;
  /** Total number of stored rows. Primary copies only — replicas are not double-counted. */
  recordCount: Scalars['Long']['output'];
  /** On-disk size of the primary copies in bytes. UIs typically format this human-readable (KiB / MiB / GiB). */
  sizeBytes: Scalars['Long']['output'];
  /** True when the backing storage table is provisioned (archive has been activated). False ⇒ RecordCount and SizeBytes are 0 and Health is Unknown. */
  tableExists: Scalars['Boolean']['output'];
};

/** Result of an archive lifecycle mutation: the archive's runtime id, its new status, and the transition name. */
export type ArchiveTransitionResult = {
  __typename?: 'ArchiveTransitionResult';
  /** Runtime id of the archive that the transition applied to. */
  archiveRtId: Scalars['OctoObjectId']['output'];
  /** New status of the archive after the transition. */
  status: Scalars['String']['output'];
  /** Name of the transition that was performed (Activate / Disable / Enable / RetryActivation). */
  transition: Scalars['String']['output'];
};

/** Defines the type of modification during write operations */
export type AssociationModOptions =
  | 'CREATE'
  | 'DELETE';

/** Who owns an attribute value, and therefore what installing the blueprint again does to it (AB#5187). SEED_OWNED: the blueprint owns the value - re-applying the blueprint OVERWRITES whatever the tenant has, and the value is carried in an exported runtime model. TENANT_OWNED: the tenant owns the value - re-applying the blueprint KEEPS the tenant's value and only seeds it on a fresh tenant, and the value IS still carried in an exported runtime model. RUNTIME_STATE: a service, operator, pipeline or job writes the value - re-applying the blueprint KEEPS it, and it is NOT carried in an exported runtime model. SECRET: a credential such as an API key, client secret, token or password - re-applying the blueprint KEEPS it, and it is NOT carried in an exported runtime model. */
export type AttributeOwnership =
  | 'RUNTIME_STATE'
  | 'SECRET'
  | 'SEED_OWNED'
  | 'TENANT_OWNED';

/** Enum of valid attribute types */
export type AttributeValueType =
  | 'BINARY'
  | 'BINARY_LINKED'
  | 'BOOLEAN'
  | 'DATE_TIME'
  | 'DATE_TIME_OFFSET'
  | 'DOUBLE'
  | 'ENUM'
  | 'GEOSPATIAL_POINT'
  | 'INT'
  | 'INTEGER'
  | 'INTEGER_64'
  | 'INTEGER_ARRAY'
  | 'INT_64'
  | 'INT_ARRAY'
  | 'RECORD'
  | 'RECORD_ARRAY'
  | 'SECRET'
  | 'STRING'
  | 'STRING_ARRAY'
  | 'TIME_SPAN';

