/** Information about pagination in a connection. */
export type PageInfo = {
  __typename?: 'PageInfo';
  /** When paginating forwards, the cursor to continue. */
  endCursor?: Maybe<Scalars['String']['output']>;
  /** When paginating forwards, are there more items? */
  hasNextPage: Scalars['Boolean']['output'];
  /** When paginating backwards, are there more items? */
  hasPreviousPage: Scalars['Boolean']['output'];
  /** When paginating backwards, the cursor to continue. */
  startCursor?: Maybe<Scalars['String']['output']>;
};

export type PointInput = {
  coordinates: PositionInput;
};

export type PositionInput = {
  latitude: Scalars['Float']['input'];
  longitude: Scalars['Float']['input'];
};

/** Aggregation query result of items */
export type QueryAggregationResult = {
  __typename?: 'QueryAggregationResult';
  /** The average value of the given attribute paths. */
  avgStatistics?: Maybe<Array<Maybe<Statistics>>>;
  /** The count of entities in the group. */
  count: Scalars['Int']['output'];
  /** The count of value of the given attribute paths that are not null. */
  countStatistics?: Maybe<Array<Maybe<Statistics>>>;
  /** The grouping input for the aggregation operation. */
  groupBy?: Maybe<Array<FieldAggregation>>;
  /** The maximum value of the given attribute paths. */
  maxStatistics?: Maybe<Array<Maybe<Statistics>>>;
  /** The minimum value of the given attribute paths. */
  minStatistics?: Maybe<Array<Maybe<Statistics>>>;
  /** The sum value of the given attribute paths. */
  sumStatistics?: Maybe<Array<Maybe<Statistics>>>;
};

/** A connection from an object to a list of objects of type `QueryAggregationResult`. */
export type QueryAggregationResultConnection = {
  __typename?: 'QueryAggregationResultConnection';
  /** A list of all of the edges returned in the connection. */
  edges?: Maybe<Array<Maybe<QueryAggregationResultEdge>>>;
  /** A list of all of the objects returned in the connection. This is a convenience field provided for quickly exploring the API; rather than querying for "{ edges { node } }" when no edge data is needed, this field can be used instead. Note that when clients like Relay need to fetch the "cursor" field on the edge to enable efficient pagination, this shortcut cannot be used, and the full "{ edges { node } } " version should be used instead. */
  items?: Maybe<Array<QueryAggregationResult>>;
  /** Information to aid in pagination. */
  pageInfo: PageInfo;
  /** A count of the total number of objects in this connection, ignoring pagination. This allows a client to fetch the first five objects by passing "5" as the argument to `first`, then fetch the total count so it could display "5 of 83", for example. In cases where we employ infinite scrolling or don't have an exact count of entries, this field will return `null`. */
  totalCount?: Maybe<Scalars['Int']['output']>;
};

/** An edge in a connection from an object to another object of type `QueryAggregationResult`. */
export type QueryAggregationResultEdge = {
  __typename?: 'QueryAggregationResultEdge';
  /** A cursor for use in pagination */
  cursor: Scalars['String']['output'];
  /** The item at the end of the edge */
  node: QueryAggregationResult;
};

/** Defines the kind of query to be executed */
export type QueryMode =
  | 'DEFAULT'
  | 'DOWNSAMPLING'
  | 'INTERPOLATION';

/** A rollup recompute run: state, row/window counts, timings, and failure reason. */
export type RecomputeJobInfo = {
  __typename?: 'RecomputeJobInfo';
  /** Wall-clock duration in milliseconds; null while running. */
  durationMs?: Maybe<Scalars['Int']['output']>;
  /** Failure reason when state is Failed; null otherwise. */
  errorReason?: Maybe<Scalars['String']['output']>;
  /** When the job reached a terminal state; null while running. */
  finishedAt?: Maybe<Scalars['DateTime']['output']>;
  /** Heartbeat of a non-terminal job: stamped when it is created or starts computing and after every committed chunk. A Running job whose heartbeat stops advancing is no longer alive; after the stale-job timeout the drain fails it as 'Presumed dead'. Null on jobs written before the field existed. */
  lastProgressAt?: Maybe<Scalars['DateTime']['output']>;
  /** Rows written into the staging table; null while pending. */
  rowsProcessed?: Maybe<Scalars['Int']['output']>;
  /** Runtime id of the recompute job. */
  rtId: Scalars['OctoObjectId']['output'];
  /** When compute started; null while pending. */
  startedAt?: Maybe<Scalars['DateTime']['output']>;
  /** Job lifecycle state: Pending / Running / Swapping / Completed / Failed / Coalesced. */
  state: Scalars['String']['output'];
  /** Buckets recomputed; null while pending. */
  windowsProcessed?: Maybe<Scalars['Int']['output']>;
};

/** Identifies a logical series (base archive + optional rtId/OBIS scope), a time window, a target point count and the required aggregation. The server picks the archive/rollup to query. */
export type ResolveSeriesQueryInput = {
  /** Runtime id of the base (raw / time-range) archive of the series' resolution family. */
  baseArchiveRtId: Scalars['OctoObjectId']['input'];
  /** How civil boundaries are resolved across mixed-timezone series (AB#4190). PerQuery (default) applies the query timeZone uniformly; PerSeries aligns each series to its own archive reference time zone. */
  comparisonPolicy?: InputMaybe<SeriesComparisonPolicy>;
  /** Inclusive start of the query window (UTC). */
  from: Scalars['DateTime']['input'];
  /** Aggregation the series must be reduced with (energy = SUM, demand = MAX, …). Never guessed; supplied by the caller. */
  requiredAggregation: CkRollupFunction;
  /** Optional source-entity rtId scope narrowing the series to a subset of source entities. Forwarded by the caller to the downsampling query. */
  rtIds?: InputMaybe<Array<Scalars['OctoObjectId']['input']>>;
  /** Logical CK attribute path of the measured column (e.g. Amount.Value) — used to match a rollup's aggregation spec. */
  sourcePath: Scalars['String']['input'];
  /** Desired number of output points (pixel-driven, ~600 typical). Must be positive. */
  targetPoints: Scalars['Int']['input'];
  /** Optional IANA time zone (e.g. Europe/Vienna) the query is resolved in (AB#4190). Aligns calendar (day/week/month/year) rungs to that zone's DST-correct civil boundaries; null ⇒ UTC. Sub-day rungs are unaffected. */
  timeZone?: InputMaybe<Scalars['String']['input']>;
  /** Exclusive end of the query window (UTC). */
  to: Scalars['DateTime']['input'];
};

/** Archive-selection decision for a resolution-aware series query: which archive to query, the effective bucket width, expected point count, reducer, and an outcome signal. */
export type ResolveSeriesQueryResult = {
  __typename?: 'ResolveSeriesQueryResult';
  /** The deliverable point count when below the requested target (ResolutionLimited / CoverageLimited) or the native raw count on the refuse path. Null when the target was met. */
  actualPoints?: Maybe<Scalars['Int']['output']>;
  /** The archive to query — a rollup, or the base archive on the refuse/raw paths. */
  archiveRtId: Scalars['OctoObjectId']['output'];
  /** Optional human-readable explanation of the chosen route / signal. On CoverageLimited (and on a refuse signal after a coverage exclusion) it names the excluded rung. */
  diagnostic?: Maybe<Scalars['String']['output']>;
  /** Width in milliseconds of one output bucket; 0 when no bucketing applies / grain unknown. */
  effectiveBucketMs: Scalars['Long']['output'];
  /** Earliest timestamp from which the finer rung excluded by the coverage filter would be usable (AB#5157). Set only when signal is CoverageLimited; null otherwise. */
  finerRungAvailableFrom?: Maybe<Scalars['DateTime']['output']>;
  /** Number of points the caller can expect from the downsampling query. */
  points: Scalars['Int']['output'];
  /** Aggregation function the downsampling query must use. */
  reducingFunction: CkRollupFunction;
  /** Outcome classification (Ok / NoSuitableRollup / ResolutionLimited / UnknownBaseGrain / EmptyLadder / CoverageLimited). CoverageLimited (AB#5157) means the coverage filter redirected the query to a coarser rung because the finer rung holds no data for the requested window; finerRungAvailableFrom says from when the finer rung could serve. */
  signal: SeriesResolutionSignal;
};

export type ResultAggregationInput = {
  avgAttributePaths?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
  countAttributePaths?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
  groupBy?: InputMaybe<FieldGroupByAggregationInput>;
  maxValueAttributePaths?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
  minValueAttributePaths?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
  sumAttributePaths?: InputMaybe<Array<InputMaybe<Scalars['String']['input']>>>;
};

/** One aggregation of a rollup: source column path plus the stored aggregation function. */
export type RollupAggregationInfo = {
  __typename?: 'RollupAggregationInfo';
  /** Stored aggregation function (Avg / Min / Max / Sum / Count). */
  function: Scalars['String']['output'];
  /** Source column path the rollup aggregates. Logical CK attribute path for single-step rollups; parent physical storage column for cascade rollups. */
  sourcePath: Scalars['String']['output'];
};

/** One aggregation: source-path on the source archive plus the aggregation function and optional explicit column name. */
export type RollupAggregationInput = {
  /** State literal a STATE_DURATION aggregation matches the source column against — a number ('2', '100'), a boolean ('true'/'false') or a string state name. Required for STATE_DURATION; ignored for every other function. */
  comparisonValue?: InputMaybe<Scalars['String']['input']>;
  /** Aggregation function (AVG materialises as two columns: {base}_sum and {base}_count). */
  function: CkRollupFunction;
  /** Attribute path on the source archive (must resolve against its captured Columns at activation time). */
  sourcePath: Scalars['String']['input'];
  /** Optional explicit storage column name. Null falls back to '{sourcePath}_{function}' lower-cased. */
  targetColumnName?: InputMaybe<Scalars['String']['input']>;
};

/** Rollup archive attached to a source CkArchive, with its schedule and current watermark. */
export type RollupArchiveInfo = {
  __typename?: 'RollupArchiveInfo';
  /** Number of aggregation specs configured on this rollup. */
  aggregationCount: Scalars['Int']['output'];
  /** The rollup's aggregation specs (source column path + stored function), for resolution-family walking. */
  aggregations: Array<RollupAggregationInfo>;
  /** Bucket-boundary alignment: FixedSize / CalendarDay / Iso8601Week / CalendarMonth / CalendarQuarter / CalendarYear. */
  bucketAlignment: Scalars['String']['output'];
  /** Bucket width in milliseconds. */
  bucketSizeMs: Scalars['Long']['output'];
  /** Number of dirty windows recorded on this archive (retroactive changes not yet propagated). 0 in the steady state. */
  dirtyWindowsPending: Scalars['Int']['output'];
  /** Upper bound of the frozen range, if set. Buckets ending at or before this point are not re-aggregated by the orchestrator. */
  frozenUntil?: Maybe<Scalars['DateTime']['output']>;
  /** Exclusive end timestamp of the most recently committed bucket. Null before the first orchestrator tick. */
  lastAggregatedBucketEnd?: Maybe<Scalars['DateTime']['output']>;
  /** Timestamp of the most recent failed recompute run. Null if the last run succeeded. */
  lastRecomputeFailureAt?: Maybe<Scalars['DateTime']['output']>;
  /** Human-readable reason for the most recent recompute failure. Null if the last run succeeded. */
  lastRecomputeFailureReason?: Maybe<Scalars['String']['output']>;
  /** Start timestamp of the most recent recompute run. Null before the first run. */
  lastRecomputeStartedAt?: Maybe<Scalars['DateTime']['output']>;
  /** Finish timestamp of the most recent successfully committed recompute run. Null before the first success. */
  lastRecomputeSuccessAt?: Maybe<Scalars['DateTime']['output']>;
  /** Number of pending recompute ranges queued on this archive (the recompute work list still to drain). 0 in the steady state. */
  pendingRecomputeRanges: Scalars['Int']['output'];
  /** True while a recompute job for this rollup is running or swapping. */
  recomputeInProgress: Scalars['Boolean']['output'];
  /** IANA reference time-zone (e.g. Europe/Vienna) that aligns calendar bucket boundaries to local wall-clock time so they are DST-correct. Null means UTC calendar boundaries. Only meaningful for the calendar bucketAlignment variants; ignored for FixedSize. */
  referenceTimeZone?: Maybe<Scalars['String']['output']>;
  /** Runtime id of the rollup archive. */
  rtId: Scalars['OctoObjectId']['output'];
  /** Optional well-known name of the rollup archive. */
  rtWellKnownName?: Maybe<Scalars['String']['output']>;
  /**
   * DEPRECATED: runtime id of the single source archive. Non-null only when the rollup declares exactly one unbounded source; null for multi-source rollups and for a single source carrying a validity span. Read 'sources' instead.
   * @deprecated Use 'sources' (AB#5157): a rollup can aggregate from several source archives with validity spans.
   */
  sourceArchiveRtId?: Maybe<Scalars['OctoObjectId']['output']>;
  /** Source archives of this rollup (AB#5157), each with its half-open validity span [validFrom, validTo). The authoritative source declaration. */
  sources: Array<RollupSourceInfo>;
  /** Current lifecycle status: Created / Activated / Disabled / Failed. */
  status: Scalars['String']['output'];
  /** Watermark lag in milliseconds — how far behind real-time the orchestrator stays before closing a bucket. */
  watermarkLagMs: Scalars['Long']['output'];
};

/** Per-rollup metadata the studio's stream-data query editor needs (bucket size, logical attribute paths derived via chain walking). */
export type RollupQueryMetadata = {
  __typename?: 'RollupQueryMetadata';
  /** Native bucket size of this rollup in milliseconds. Drives the downsampling bucket-alignment warning. */
  bucketSizeMs: Scalars['Long']['output'];
  /** Distinct logical CK-attribute paths the rollup aggregates over. For cascade rollups these are derived via chain walking (RollupLogicalPathResolver). */
  logicalSourcePaths: Array<Scalars['String']['output']>;
  /** Runtime id of the rollup archive — echo of the request argument. */
  rtId: Scalars['OctoObjectId']['output'];
};

/** One source archive of a rollup plus its half-open validity span. validFrom inclusive, validTo exclusive; null = unbounded in that direction. */
export type RollupSourceInfo = {
  __typename?: 'RollupSourceInfo';
  /** Runtime id of the source archive (raw CkArchive, TimeRangeArchive or another CkRollupArchive). */
  sourceArchiveRtId: Scalars['OctoObjectId']['output'];
  /** Inclusive start of the validity span. Null = the source is authoritative for all buckets before validTo. */
  validFrom?: Maybe<Scalars['DateTime']['output']>;
  /** Exclusive end of the validity span. Null = the source is authoritative for all buckets from validFrom onwards. */
  validTo?: Maybe<Scalars['DateTime']['output']>;
};

